class _Official_bench_custom_FFT:
    params = [[10000000]]
    param_names = ['length']

    def setup(self, length):
        t_arr = np.linspace(0.0, 1.0, length, dtype=np.float64)
        self.signal = np.sin(2 * np.pi * 50 * t_arr) + 0.5 * np.sin(2 * np.pi * 120 * t_arr) + np.random.randn(length) * 0.3

    def time_fft(self, length):
        np.fft.fft(self.signal)

class _Official_bench_custom_ElementwiseBroadcast:
    params = [[4000]]
    param_names = ['n']

    def setup(self, n):
        self.X = np.random.randn(n, n).astype(np.float64)

    def time_normalise_and_sigmoid(self, n):
        row_mean = self.X.mean(axis=1, keepdims=True)
        row_std = self.X.std(axis=1, keepdims=True) + 1e-08
        Z = (self.X - row_mean) / row_std
        _ = 1.0 / (1.0 + np.exp(-Z))

